const fs = require('fs');
const path = require('path');

const file = process.argv[2] || path.join(__dirname, 'README.md');
const needle = 'TODO';
const text = fs.readFileSync(file, 'utf8');

let count = 0;
let index = 0;
while ((index = text.indexOf(needle, index)) !== -1) {
  count += 1;
  index += needle.length;
}

console.log(count);

